// "Return a new list containing all items from the iterable in ascending order."
// Helper: a sequence is in ascending (non-decreasing) order.
predicate IsSortedAsc(s: seq<int>)
{
  forall i, j :: 0 <= i < j < |s| ==> s[i] <= s[j]
}

// Helper for PySorted: insert x into an ascending sequence, keeping it ascending.
function InsertSorted(x: int, s: seq<int>): seq<int>
  decreases |s|
{
  if |s| == 0 then [x]
  else if x <= s[0] then [x] + s
  else [s[0]] + InsertSorted(x, s[1..])
}

// "Return a new list containing all items from the iterable in ascending order."
// Models sorted(s) with no key and reverse=False. The result is a permutation of s
// in non-decreasing order. Defined here by insertion sort.
function PySorted(s: seq<int>): seq<int>
  decreases |s|
{
  if |s| == 0 then []
  else InsertSorted(s[0], PySorted(s[1..]))
}

// Python slice semantics: s[::-1] is "a new list with the items of s in reverse order"
// (start and stop default to the ends of the sequence, step -1).
function SliceReverse<T>(s: seq<T>): seq<T>
  decreases |s|
{
  if |s| == 0 then []
  else SliceReverse(s[1..]) + [s[0]]
}

// "Append object to the end of the list."
// Models lst.append(x): the list's new value is lst with x added at the end.
function ListAppend<T>(lst: seq<T>, x: T): seq<T>
{
  lst + [x]
}
