// round: "The return value is an integer if ndigits is omitted or None."
// Python reference docs: "if two multiples are equally close, rounding is done toward
// the even choice (so, for example, both round(0.5) and round(-0.5) are 0, and round(1.5) is 2)."
function Round(x: real): int
{
  var f := x.Floor;
  var d := x - f as real;
  if d < 1.0 / 2.0 then f
  else if d > 1.0 / 2.0 then f + 1
  else (if f % 2 == 0 then f else f + 1)
}

