// synth: lemma
lemma DVPrepend(c: char, s: string, base: int)
  requires AllDigits([c] + s, base)
  ensures DigitsValue([c] + s, base) == DigitVal(c) * Pow(base, |s|) + DigitsValue(s, base)
  decreases |s|
{
  var t := [c] + s;
  assert t[0] == c;
  assert '0' <= c <= '9';
  if |s| == 0 {
    assert t[..|t|-1] == [];
    assert t[|t|-1] == c;
    assert DigitsValue(t, base) == DigitsValue([], base) * base + DigitVal(c);
  } else {
    var s' := s[..|s|-1];
    assert t[..|t|-1] == [c] + s';
    assert t[|t|-1] == s[|s|-1];
    assert forall i :: 0 <= i < |[c] + s'| ==> ([c] + s')[i] == t[i];
    assert AllDigits([c] + s', base);
    DVPrepend(c, s', base);
    assert '0' <= t[|t|-1] <= '9';
    assert s[|s|-1] != '_';
    assert DigitsValue(s, base) == DigitsValue(s', base) * base + DigitVal(s[|s|-1]);
    assert t[|t|-1] != '_';
    assert DigitsValue(t, base) == DigitsValue([c] + s', base) * base + DigitVal(s[|s|-1]);
    assert Pow(base, |s|) == base * Pow(base, |s'|);
    assert (DigitVal(c) * Pow(base, |s'|) + DigitsValue(s', base)) * base
        == DigitVal(c) * (base * Pow(base, |s'|)) + DigitsValue(s', base) * base;
  }
}

