// Library theory for: all, min, filter, and Python's % operator.

// Python `%`: "The modulo operator always yields a result with the same sign as its
// second operand (or zero); the absolute value of the result is strictly smaller
// than the absolute value of the second operand." Also x == (x//y)*y + (x%y).
// Dafny's % on int is Euclidean (result in [0, |b|)), so adjust when b < 0.
function PyMod(a: int, b: int): int
  requires b != 0
{
  var r := a % b;
  if b < 0 && r != 0 then r + b else r
}

// all: "Return True if bool(x) is True for all values x in the iterable.
//       If the iterable is empty, return True."
function All(s: seq<bool>): bool
{
  if |s| == 0 then true else s[0] && All(s[1..])
}

// filter: "Return an iterator yielding those items of iterable for which
//          function(item) is true." (order preserved)
function Filter<T>(f: T -> bool, s: seq<T>): seq<T>
{
  if |s| == 0 then []
  else if f(s[0]) then [s[0]] + Filter(f, s[1..])
  else Filter(f, s[1..])
}

// min: "With a single iterable argument, return its smallest item."
// (An empty iterable without default raises ValueError, hence the precondition.)
function Min(s: seq<int>): int
  requires |s| > 0
{
  if |s| == 1 then s[0]
  else
    var m := Min(s[1..]);
    if s[0] <= m then s[0] else m
}
