function StrSplit(s: string, sep: string): seq<string>
  requires |sep| > 0
  ensures |StrSplit(s, sep)| >= 1
  decreases |s|
{
  if |s| < |sep| then [s]
  else if s[..|sep|] == sep then [""] + StrSplit(s[|sep|..], sep)
  else
    var r := StrSplit(s[1..], sep);
    [[s[0]] + r[0]] + r[1..]
